"import Navbar from './components/Navbar';
import Hero from './components/Hero';
import './index.css';

function App() {
  return (
    <div className="portfolio-container">
      <div className="bg-grey-split"></div>
      <div className="content-wrapper">
        <Navbar />
        <Hero />
      </div>
    </div>
  )
}

export default App;
"

"@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --color-grey: #E5E5E5;
  --color-black: #000000;
  --color-white: #FFFFFF;
  --color-dark-grey: #828282;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--color-black);
  color: var(--color-white);
  overflow-x: hidden;
}

.portfolio-container {
  position: relative;
  min-height: 100vh;
  width: 100%;
}

.bg-grey-split {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: var(--color-grey);
  /* Desktop split: wider grey on the left */
  clip-path: polygon(0 0, 52% 0, 42% 100%, 0 100%);
  z-index: 0;
}

.content-wrapper {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

@media (max-width: 900px) {
  .bg-grey-split {
    /* Mobile split: top half is grey */
    clip-path: polygon(0 0, 100% 0, 100% 55%, 0 65%);
  }
}
"

"import React from 'react';
import './Navbar.css';

const Navbar = () => {
  return (
    <nav className="navbar">
      <div className="nav-logo">
        <span className="logo-text">TD</span>
      </div>
      <div className="nav-links">
        <a href="#about">About me</a>
        <a href="#skills">Skills</a>
        <a href="#portfolio">Portfolio</a>
        <a href="#contact" className="contact-btn">CONTACT ME</a>
      </div>
    </nav>
  );
};

export default Navbar;"

".navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2.5rem 6%;
}

.nav-logo .logo-text {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--color-black);
  letter-spacing: -2px;
  /* Add the logo icon shape matching sample */
  display: flex;
  align-items: center;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 3rem;
}

.nav-links a {
  text-decoration: none;
  color: var(--color-white);
  font-weight: 600;
  font-size: 0.95rem;
  transition: color 0.3s;
}

.nav-links a:hover {
  color: var(--color-grey);
}

.contact-btn {
  background-color: var(--color-white);
  color: var(--color-black) !important;
  padding: 0.7rem 1.8rem;
  border-radius: 30px;
  font-weight: 700 !important;
  font-size: 0.85rem !important;
  transition: transform 0.3s, box-shadow 0.3s;
}

.contact-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(255, 255, 255, 0.2);
}

@media (max-width: 900px) {
  .navbar {
    padding: 1.5rem 5%;
  }

  .nav-links {
    display: none; /* Hide on small screens for now, or adapt later */
  }
}"

"import React from 'react';
import { motion } from 'framer-motion';
import { Mail, Github, Linkedin } from 'lucide-react';
import './SocialIcons.css';

const SocialIcons = () => {
  const floatVariant = (delay) => ({
    animate: {
      y: [0, -8, 0],
      transition: {
        repeat: Infinity,
        duration: 3,
        ease: "easeInOut",
        delay: delay
      }
    }
  });

  return (
    <div className="social-icons">
      <motion.a 
        href="#"
        className="social-icon"
        variants={floatVariant(0)}
        animate="animate"
        whileHover={{ scale: 1.1, backgroundColor: "#ffffff" }}
      >
        <Mail size={22} strokeWidth={2.5} />
      </motion.a>
      <motion.a 
        href="#"
        className="social-icon"
        variants={floatVariant(0.4)}
        animate="animate"
        whileHover={{ scale: 1.1, backgroundColor: "#ffffff" }}
      >
        <Github size={22} strokeWidth={2.5} />
      </motion.a>
      <motion.a 
        href="#"
        className="social-icon"
        variants={floatVariant(0.8)}
        animate="animate"
        whileHover={{ scale: 1.1, backgroundColor: "#ffffff" }}
      >
        <Linkedin size={22} strokeWidth={2.5} />
      </motion.a>
    </div>
  );
};

export default SocialIcons;"

".social-icons {
  display: flex;
  gap: 1.2rem;
}

.social-icon {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 45px;
  height: 45px;
  background-color: #d6d6d6;
  color: var(--color-black);
  border-radius: 4px;
  text-decoration: none;
  box-shadow: 2px 4px 10px rgba(0, 0, 0, 0.1);
  transition: box-shadow 0.3s;
}

.social-icon:hover {
  box-shadow: 4px 8px 15px rgba(0, 0, 0, 0.15);
}"

"import React from 'react';
import { motion } from 'framer-motion';
import SocialIcons from './SocialIcons';
import './Hero.css';

const Hero = () => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: { 
      opacity: 1, 
      y: 0,
      transition: { duration: 0.6, ease: [0.6, -0.05, 0.01, 0.99] }
    }
  };

  return (
    <section className="hero">
      <motion.div 
        className="hero-content"
        variants={containerVariants}
        initial="hidden"
        animate="visible"
      >
        <motion.p className="greeting" variants={itemVariants}>Hi, I am</motion.p>
        <motion.h1 className="name" variants={itemVariants}>Tushar Das</motion.h1>
        <motion.p className="title" variants={itemVariants}>B.Tech CSE Student / Full-Stack Developer</motion.p>
        <motion.div variants={itemVariants} className="icons-container">
          <SocialIcons />
        </motion.div>
      </motion.div>
      <div className="hero-image-container">
        <motion.img 
          src="/hero-image.png" 
          alt="Tushar Das" 
          className="hero-image"
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.8, delay: 0.4, ease: "easeOut" }}
        />
      </div>
    </section>
  );
};

export default Hero;"

".hero {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 6%;
}

.hero-content {
  flex: 1;
  max-width: 50%;
  color: var(--color-black);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.greeting {
  font-size: 1.6rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.name {
  font-size: 4.8rem;
  font-weight: 800;
  letter-spacing: -2px;
  line-height: 1.1;
  margin-bottom: 0.5rem;
}

.title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-dark-grey);
  margin-bottom: 3.5rem;
  letter-spacing: 0px;
}

.hero-image-container {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  height: calc(100vh - 100px); /* Fill remaining height */
  overflow: hidden;
}

.hero-image {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  object-position: bottom;
  margin-bottom: -5px; /* Ensures image touches the bottom cleanly */
}

@media (max-width: 900px) {
  .hero {
    flex-direction: column;
    justify-content: flex-start;
    padding-top: 2rem;
  }

  .hero-content {
    max-width: 100%;
    align-items: center;
    text-align: center;
    margin-bottom: 2rem;
  }

  .name {
    font-size: 3.5rem;
  }

  .hero-image-container {
    height: 50vh;
  }
}"

